html:
{%- macro money(value) -%}{{ frappe.utils.fmt_money(value or 0, currency=doc.currency) }}{%- endmacro -%}
{%- set earnings = doc.earnings | rejectattr("do_not_include_in_total") | selectattr("amount") | list -%}
{%- set deductions = doc.deductions | rejectattr("do_not_include_in_total") | selectattr("amount") | list -%}
{%- set show_tax = doc.annual_taxable_amount or doc.total_income_tax or doc.ctc -%}

<style>
	.ss-doc {
		font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
		color: #1a1a1a;
		font-size: 12px;
		line-height: 1.45;
	}
	.ss-doc table { border-collapse: collapse; width: 100%; }
	.ss-doc td, .ss-doc th { vertical-align: top; padding: 0; }
	.ss-doc .letter-head { margin-bottom: 12px; }
	.ss-num { font-variant-numeric: tabular-nums; white-space: nowrap; }
	.ss-right { text-align: right; }
	.ss-label {
		font-size: 9.5px;
		letter-spacing: 0.1em;
		text-transform: uppercase;
		color: #757575;
		font-weight: bold;
	}
	.ss-head-rule { border-top: 2px solid #1a1a1a; margin-bottom: 16px; }
	.ss-title h3 {
		margin: 0;
		font-size: 15px;
		font-weight: bold;
		letter-spacing: 0.1em;
		text-transform: uppercase;
	}
	.ss-title .ss-period { font-size: 11.5px; color: #757575; margin-top: 2px; }
	.ss-ref { font-size: 10.5px; color: #757575; }
	.ss-ref strong { display: block; color: #1a1a1a; font-size: 11.5px; }
	.ss-meta {
		border-top: 1px solid #e2e2e2;
		border-bottom: 1px solid #e2e2e2;
		padding: 12px 0;
		margin: 16px 0 0;
	}
	.ss-meta td { width: 50%; }
	.ss-meta td + td { padding-left: 40px; }
	.ss-kv { width: 100%; }
	.ss-kv td { padding: 3px 0; font-size: 11px; }
	.ss-kv td.k { color: #757575; }
	.ss-kv td.v { text-align: right; font-size: 11.5px; font-weight: bold; }
	.ss-strip { margin-top: 18px; border: 1px solid #e2e2e2; background-color: #f6f6f6; }
	.ss-strip td { padding: 9px 12px; border-right: 1px solid #e2e2e2; width: 20%; }
	.ss-strip td.last { border-right: none; }
	.ss-strip .ss-label { line-height: 1.3; min-height: 25px; }
	.ss-strip .v { font-size: 15px; font-weight: bold; margin-top: 2px; }
	.ss-section { margin: 24px 0 10px; }
	.ss-section td.rule { width: 100%; padding-left: 12px; vertical-align: middle; }
	.ss-section td.rule div { border-top: 1px solid #e2e2e2; }
	.ss-ledger th {
		font-size: 9.5px;
		letter-spacing: 0.06em;
		text-transform: uppercase;
		color: #757575;
		font-weight: bold;
		border-bottom: 1px solid #b0b0b0;
		padding-bottom: 5px;
		text-align: right;
	}
	.ss-ledger th.c { text-align: left; }
	.ss-ledger td {
		padding: 5px 0;
		border-bottom: 1px solid #e2e2e2;
		font-size: 11.5px;
		text-align: right;
	}
	.ss-ledger td.c { text-align: left; color: #444444; }
	.ss-ledger tr.ss-total td {
		border-bottom: none;
		border-top: 1px solid #b0b0b0;
		padding-top: 7px;
		font-weight: bold;
		font-size: 12px;
		color: #1a1a1a;
	}
	.ss-ledger col.amt { width: 24%; }
	.ss-net {
		background-color: #f2f2f2;
		border-left: 3px solid #1a1a1a;
		margin-top: 20px;
	}
	.ss-net td { padding: 14px 18px; }
	.ss-net .words { font-size: 10.5px; color: #757575; margin-top: 3px; }
	.ss-net .amt {
		font-size: 21px;
		font-weight: bold;
		white-space: nowrap;
		text-align: right;
	}
	.ss-net td.right { text-align: right; }
	.ss-split { margin-top: 24px; }
	.ss-split > tbody > tr > td { width: 50%; }
	.ss-split > tbody > tr > td.l { padding-right: 18px; }
	.ss-split > tbody > tr > td.r { padding-left: 18px; }
	.ss-foot {
		margin-top: 22px;
		padding-top: 10px;
		border-top: 1px solid #e2e2e2;
		font-size: 9.5px;
		color: #757575;
	}
</style>

<div class="ss-doc ss-detailed">
	{% if letter_head and not no_letterhead %}
	<div class="letter-head">{{ letter_head }}</div>
	{% endif %}
	<div class="ss-head-rule"></div>

	<table class="ss-title">
		<tr>
			<td>
				<h3>{{ _("Salary Statement") }}</h3>
				<div class="ss-period">
					{{ frappe.format(doc.start_date, {"fieldtype": "Date"}) }}
					{{ _("to") }} {{ frappe.format(doc.end_date, {"fieldtype": "Date"}) }}
					{%- if doc.current_payroll_period %} &bull; {{ _("Payroll Period") }} {{ doc.current_payroll_period }}{% endif %}
				</div>
			</td>
			<td class="ss-ref ss-right">
				<strong>{{ doc.name }}</strong>
				{{ _("Issued") }} {{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}
			</td>
		</tr>
	</table>

	<table class="ss-meta">
		<tr>
			<td>
				<table class="ss-kv">
					<tr><td class="k">{{ _("Employee Name") }}</td><td class="v">{{ doc.employee_name }}</td></tr>
					<tr><td class="k">{{ _("Employee ID") }}</td><td class="v ss-num">{{ doc.employee }}</td></tr>
					{% if doc.designation %}<tr><td class="k">{{ _("Designation") }}</td><td class="v">{{ doc.designation }}</td></tr>{% endif %}
					{% if doc.department %}<tr><td class="k">{{ _("Department") }}</td><td class="v">{{ doc.department }}</td></tr>{% endif %}
				</table>
			</td>
			<td>
				<table class="ss-kv">
					{% if doc.branch %}<tr><td class="k">{{ _("Branch") }}</td><td class="v">{{ doc.branch }}</td></tr>{% endif %}
					{% if doc.salary_structure %}<tr><td class="k">{{ _("Salary Structure") }}</td><td class="v">{{ doc.salary_structure }}</td></tr>{% endif %}
					{% if doc.payroll_frequency %}<tr><td class="k">{{ _("Payroll Frequency") }}</td><td class="v">{{ _(doc.payroll_frequency) }}</td></tr>{% endif %}
					{% if doc.exchange_rate and doc.exchange_rate != 1 %}<tr><td class="k">{{ _("Exchange Rate") }}</td><td class="v ss-num">{{ doc.exchange_rate }}</td></tr>{% endif %}
				</table>
			</td>
		</tr>
	</table>

	<table class="ss-strip">
		<tr>
			<td>
				<div class="ss-label">{{ _("Working Days") }}</div>
				<div class="v ss-num">{{ doc.total_working_days }}</div>
			</td>
			<td>
				<div class="ss-label">{{ _("Payment Days") }}</div>
				<div class="v ss-num">{{ doc.payment_days }}</div>
			</td>
			<td>
				<div class="ss-label">{{ _("Leave Without Pay") }}</div>
				<div class="v ss-num">{{ doc.leave_without_pay }}</div>
			</td>
			<td>
				<div class="ss-label">{{ _("Absent Days") }}</div>
				<div class="v ss-num">{{ doc.absent_days }}</div>
			</td>
			<td class="last">
				<div class="ss-label">{{ _("Unmarked Days") }}</div>
				<div class="v ss-num">{{ doc.unmarked_days }}</div>
			</td>
		</tr>
	</table>

	<table class="ss-section">
		<tr>
			<td class="ss-label" style="white-space: nowrap;">{{ _("Earnings") }}</td>
			<td class="rule"><div></div></td>
		</tr>
	</table>
	<table class="ss-ledger">
		<colgroup><col><col class="amt"><col class="amt"></colgroup>
		<thead>
			<tr>
				<th class="c">{{ _("Component") }}</th>
				<th>{{ _("This Period") }}</th>
				<th>{{ _("Year to Date") }}</th>
			</tr>
		</thead>
		<tbody>
			{% for row in earnings %}
			<tr>
				<td class="c">{{ _(row.salary_component) }}</td>
				<td class="ss-num">{{ money(row.amount) }}</td>
				<td class="ss-num">{{ money(row.year_to_date) }}</td>
			</tr>
			{% endfor %}
			<tr class="ss-total">
				<td class="c">{{ _("Gross Pay") }}</td>
				<td class="ss-num">{{ money(doc.gross_pay) }}</td>
				<td class="ss-num">{{ money(doc.gross_year_to_date) }}</td>
			</tr>
		</tbody>
	</table>

	<table class="ss-section">
		<tr>
			<td class="ss-label" style="white-space: nowrap;">{{ _("Deductions") }}</td>
			<td class="rule"><div></div></td>
		</tr>
	</table>
	<table class="ss-ledger">
		<colgroup><col><col class="amt"><col class="amt"></colgroup>
		<thead>
			<tr>
				<th class="c">{{ _("Component") }}</th>
				<th>{{ _("This Period") }}</th>
				<th>{{ _("Year to Date") }}</th>
			</tr>
		</thead>
		<tbody>
			{% for row in deductions %}
			<tr>
				<td class="c">{{ _(row.salary_component) }}</td>
				<td class="ss-num">{{ money(row.amount) }}</td>
				<td class="ss-num">{{ money(row.year_to_date) }}</td>
			</tr>
			{% endfor %}
			<tr class="ss-total">
				<td class="c">{{ _("Total Deduction") }}</td>
				<td class="ss-num">{{ money(doc.total_deduction) }}</td>
				<td class="ss-num">{{ money(deductions | sum(attribute="year_to_date")) }}</td>
			</tr>
		</tbody>
	</table>

	<table class="ss-net">
		<tr>
			<td>
				<div class="ss-label">{{ _("Net Pay") }}</div>
				<div class="words">{{ doc.total_in_words }}</div>
			</td>
			<td class="right">
				<div class="amt ss-num">{{ money(doc.rounded_total or doc.net_pay) }}</div>
				<div class="words">{{ _("Net paid year to date") }} {{ money(doc.year_to_date) }}</div>
			</td>
		</tr>
	</table>

	{% if doc.leave_details or show_tax %}
	<table class="ss-split">
		<tr>
			<td class="l">
				{% if doc.leave_details %}
				<table class="ss-ledger">
					<thead>
						<tr>
							<th class="c">{{ _("Leave Type") }}</th>
							<th>{{ _("Used") }}</th>
							<th>{{ _("Available") }}</th>
						</tr>
					</thead>
					<tbody>
						{% for row in doc.leave_details %}
						<tr>
							<td class="c">{{ _(row.leave_type) }}</td>
							<td class="ss-num">{{ row.used_leaves }}</td>
							<td class="ss-num">{{ row.available_leaves }}</td>
						</tr>
						{% endfor %}
					</tbody>
				</table>
				{% endif %}
			</td>
			<td class="r">
				{% if show_tax %}
				<table class="ss-ledger">
					<thead>
						<tr>
							<th class="c">{{ _("Income Tax Working") }}</th>
							<th>{{ _("Annual") }}</th>
						</tr>
					</thead>
					<tbody>
						{% if doc.ctc %}<tr><td class="c">{{ _("CTC") }}</td><td class="ss-num">{{ money(doc.ctc) }}</td></tr>{% endif %}
						{% if doc.total_earnings %}<tr><td class="c">{{ _("Total Earnings") }}</td><td class="ss-num">{{ money(doc.total_earnings) }}</td></tr>{% endif %}
						{% if doc.tax_exemption_declaration %}<tr><td class="c">{{ _("Tax Exemption Declaration") }}</td><td class="ss-num">{{ money(doc.tax_exemption_declaration) }}</td></tr>{% endif %}
						{% if doc.standard_tax_exemption_amount %}<tr><td class="c">{{ _("Standard Tax Exemption") }}</td><td class="ss-num">{{ money(doc.standard_tax_exemption_amount) }}</td></tr>{% endif %}
						{% if doc.annual_taxable_amount %}<tr><td class="c">{{ _("Annual Taxable Amount") }}</td><td class="ss-num">{{ money(doc.annual_taxable_amount) }}</td></tr>{% endif %}
						{% if doc.total_income_tax %}
						<tr class="ss-total">
							<td class="c">{{ _("Total Income Tax") }}</td>
							<td class="ss-num">{{ money(doc.total_income_tax) }}</td>
						</tr>
						{% endif %}
					</tbody>
				</table>
				{% endif %}
			</td>
		</tr>
	</table>
	{% endif %}

	<table class="ss-foot">
		<tr>
			<td>
				{%- if doc.bank_name -%}
					{{ doc.bank_name }}
					{%- if doc.bank_account_no %} &bull; {{ _("A/C") }} {{ doc.bank_account_no }}{% endif -%}
					{%- if doc.mode_of_payment %} &bull; {{ _(doc.mode_of_payment) }}{% endif -%}
				{%- elif doc.mode_of_payment -%}
					{{ _("Paid by") }} {{ _(doc.mode_of_payment) }}
				{%- endif -%}
			</td>
			<td class="ss-right">{{ _("This is a computer generated document and does not require a signature.") }}</td>
		</tr>
	</table>
</div>
